export function labels(language){const list=(VALUES[language]||VALUES.EN).split('|');return Object.fromEntries(UI_KEYS.map((key,i)=>[key,list[i]]));}
export function optionLabels(language,index){if(index===1)return ({EN:'Day|Dawn (before sunrise)|Sunrise|Golden hour|Sunset|Dusk (after sunset)|Blue hour|Night|Custom',HU:'Nappal|Hajnal (napkelte előtt)|Napkelte|Aranyóra|Napnyugta|Alkonyat (napnyugta után)|Kék óra|Éjszaka|Egyéni',DE:'Tag|Morgengrauen|Sonnenaufgang|Goldene Stunde|Sonnenuntergang|Dämmerung|Blaue Stunde|Nacht|Eigene Angabe',FR:'Jour|Aube|Lever du soleil|Heure dorée|Coucher du soleil|Crépuscule|Heure bleue|Nuit|Personnalisé',ES:'Día|Alba|Amanecer|Hora dorada|Puesta de sol|Crepúsculo|Hora azul|Noche|Personalizado',IT:'Giorno|Aurora|Alba|Ora dorata|Tramonto|Crepuscolo|Ora blu|Notte|Personalizzato',PT:'Dia|Alvorada|Nascer do sol|Hora dourada|Pôr do sol|Crepúsculo|Hora azul|Noite|Personalizado',PL:'Dzień|Brzask|Wschód słońca|Złota godzina|Zachód słońca|Zmierzch|Niebieska godzina|Noc|Własne'}[language]||'Day|Dawn|Sunrise|Golden hour|Sunset|Dusk|Blue hour|Night|Custom').split('|');return (OPTIONS[language]||OPTIONS.EN)[index].split('|');}
export function validateLabels(){return Object.keys(VALUES).every(lang=>VALUES[lang].split('|').length===UI_KEYS.length&&OPTIONS[lang].length===6&&OPTIONS[lang].every((v,i)=>v.split('|').length===[8,4,5,5,4,3][i]));}
